const servers = ns.scan('home');
// Find the server with the highest potential money
let targetServer = null;
let maxPotentialMoney = 0;
for (const server of servers) {
  const serverInfo = ns.getServer(server);
  if (serverInfo.hasAdminRights && serverInfo.moneyAvailable > maxPotentialMoney && ns.hackAnalyzeChance(server) > 0.9) {
    targetServer = server;
    maxPotentialMoney = serverInfo.moneyAvailable;
  }
}
