  await ns.hack(targetServer);
}

// @param {NS} ns
export async function main(ns) {
  const servers = ns.scan('home');
  let maxMoneyServer = null;
  for (const server of servers) {
    if (ns.hasAdminAccess(server)) {
      if (!maxMoneyServer || ns.getServerMaxMoney(server) > ns.getServerMaxMoney(maxMoneyServer)) {
        maxMoneyServer = server;
      }
    }
  }
  if (maxMoneyServer) {
    await ns.hack(maxMoneyServer);
  }
}

