/** @param {NS} ns */
export async function main(ns) {
  const servers = ns.scan();
  let targetServer = null;
  let highestMoney = 0;

  for (const server of servers) {
    if (ns.hasRootAccess(server) && ns.getServerMaxMoney(server) > highestMoney) {
      targetServer = server;
      highestMoney = ns.getServerMaxMoney(server);
    }
  }

  if (targetServer) {
    await ns.hack(targetServer);
  }
}
